# Nested group default_map
@click.group()
def grp(): pass
@grp.command()
@click.option('--port', default=8000, show_default=True)
def serve(port): click.echo(f'port={port!r}')
r = CliRunner().invoke(grp, ['serve'], default_map={'serve': {'port': UNSET}})
print('nested:', repr(r.output), r.exception); assert r.output == 'port=8000\n'
r = CliRunner().invoke(grp, ['serve', '--help'], default_map={'serve': {'port': UNSET}})
print('help:', repr(r.output))
